export const DICTIONARIES = Object.freeze({
  ru: Object.freeze(russian),
  en: Object.freeze(Object.fromEntries(Object.keys(russian).map((key) => [key, key])))
});
export const normalizeLanguage = (value) => LANGUAGES.includes(value) ? value : DEFAULT_LANGUAGE;

export function readLanguage(storage) {
  try { return normalizeLanguage(JSON.parse((storage ?? globalThis.localStorage)?.getItem(SAVE_KEY) || "null")?.settings?.lang); }
  catch { return DEFAULT_LANGUAGE; }
}

export function saveLanguage(value, storage) {
  try {
    storage ??= globalThis.localStorage;
    if (!storage) return false;
    // A language-only save uses the current schema so legacy migration cannot create a profile.
    const save = JSON.parse(storage.getItem(SAVE_KEY) || '{"version":5}');
    if (!save || typeof save !== "object" || Array.isArray(save)) return false;
    const settings = save.settings && typeof save.settings === "object" && !Array.isArray(save.settings) ? save.settings : {};
    storage.setItem(SAVE_KEY, JSON.stringify({ ...save, settings: { ...settings, lang: normalizeLanguage(value) } }));
    return true;
  } catch { return false; }
}

let language = readLanguage();
const listeners = new Set();
export const getLanguage = () => language;
export function setLanguage(value, { persist = true } = {}) {
  const next = normalizeLanguage(value);
  if (persist) saveLanguage(next);
  if (next === language) return language;
  language = next;
  if (globalThis.document) document.documentElement.lang = language;
  for (const listener of listeners) listener(language);
  return language;
}
export function onLanguageChange(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function t(key, params = {}) {
  const text = DICTIONARIES[language][key] ?? (/^[a-z][\w-]*(?:\.[\w-]+)+$/.test(key) ? "" : String(key));
  return text.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(params, name) ? String(params[name]) : match);
}

export function formatCoins(value) {
  const amount = Number(value) || 0;
  if (language === "en") return `${amount} ${amount === 1 ? "coin" : "coins"}`;
  const n = Math.abs(amount), last = n % 10, lastTwo = n % 100;
  const word = last === 1 && lastTwo !== 11 ? "\u043c\u043e\u043d\u0435\u0442\u0430"
    : last >= 2 && last <= 4 && (lastTwo < 12 || lastTwo > 14) ? "\u043c\u043e\u043d\u0435\u0442\u044b" : "\u043c\u043e\u043d\u0435\u0442";
  return `${amount} ${word}`;
}

const escapePattern = (value) => value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const templates = Object.keys(russian).filter((key) => key.includes("{"))
  .sort((a, b) => b.replace(/\{\w+\}/g, "").length - a.replace(/\{\w+\}/g, "").length).map((key) => {
  const names = [...key.matchAll(/\{(\w+)\}/g)].map((match) => match[1]);
  const pattern = key.split(/\{\w+\}/).map(escapePattern).join("(.+?)");
  return { key, names, pattern: new RegExp(`^${pattern}$`) };
});

export function errorMessage(error, fallback) {
  const message = String(error?.message || "");
  return Object.hasOwn(russian, message) || templates.some((template) => template.pattern.test(message)) ? message : fallback;
}

// Compatibility for legacy display strings; new messages should use t with parameters.
export function translateText(value) {
  const text = String(value ?? "");
  if (language === "en" || !text.trim()) return text;
  const trimmed = text.trim().replace(/\s+/g, " ");
  let result = russian[trimmed];
  if (result === undefined) {
    for (const template of templates) {
      const match = trimmed.match(template.pattern);
      if (!match) continue;
      const params = Object.fromEntries(template.names.map((name, i) => [name, match[i + 1]]));
      if (params.name && /purchased|equipped|Bait:/.test(template.key)) params.name = t(params.name);
      if (params.view) params.view = t(params.view);
      if (params.surface) params.surface = t(params.surface === "bed" ? "Bed" : params.surface === "dock" ? "Dock" : "Land");
      result = t(template.key, params);
      break;
    }
  }
  if (result === undefined && /^\d+(?:\.\d+)? coins?$/.test(trimmed)) result = formatCoins(trimmed.split(" ")[0]);
  if (result === undefined && /^\d+h \d+m$/.test(trimmed)) result = trimmed.replace("h", " \u0447").replace("m", " \u043c\u0438\u043d");
  if (result === undefined && /^[\d. /]+ (m|cm|kg)$/.test(trimmed)) result = trimmed.replace(/(cm|kg|m)$/, (unit) => ({ cm: "\u0441\u043c", kg: "\u043a\u0433", m: "\u043c" })[unit]);
  if (result === undefined && /^\d+(?:\.\d+)? cm \/ \d+(?:\.\d+)? kg$/.test(trimmed)) result = trimmed.replace("cm", "\u0441\u043c").replace("kg", "\u043a\u0433");
  if (result === undefined && /^SnejFishing v[\w.-]+ Stage \w+ \(c\) \d{4}$/.test(trimmed)) result = trimmed.replace("Stage", t("Stage"));
  if (result === undefined) return text;
  return text.slice(0, text.indexOf(text.trim())) + result + text.slice(text.indexOf(text.trim()) + text.trim().length);
}

const originals = new WeakMap();
const englishSources = new Map(Object.entries(russian).map(([key, value]) => [value, key]));
const sourceText = (value) => englishSources.get(value) ?? value;
const skipSelector = "[data-i18n-skip], script, style, textarea, #profile-name, #launcher-profile-name, #launcher-profile-initial, #equipment-player-name, .texture-name, .loadout-card h4";
export function applyTranslations(root = globalThis.document) {
  if (!root) return;
  const doc = root.ownerDocument || root;
  if (doc.documentElement) doc.documentElement.lang = language;
  const walker = doc.createTreeWalker(root, 4);
  const translateNode = (node) => {
    if (node.parentElement?.closest(skipSelector)) return;
    const previous = originals.get(node);
    const source = previous && node.nodeValue === previous.rendered ? previous.source : sourceText(node.nodeValue);
    const rendered = translateText(source);
    if (node.nodeValue !== rendered) node.nodeValue = rendered;
    originals.set(node, { source, rendered });
  };
  if (root.nodeType === 3) translateNode(root);
  while (walker.nextNode()) translateNode(walker.currentNode);
  const elements = root.querySelectorAll?.("[aria-label], [aria-valuetext], [title], [placeholder], [data-i18n]") || [];
  const translateElement = (element) => {
    if (element.closest(skipSelector)) return;
    if (element.dataset.i18n) element.textContent = t(element.dataset.i18n);
    const previous = originals.get(element) || {};
    for (const attr of ["aria-label", "aria-valuetext", "title", "placeholder"]) {
      if (!element.hasAttribute(attr)) continue;
      const current = element.getAttribute(attr);
      const source = previous[attr] && current === previous[attr].rendered ? previous[attr].source : sourceText(current);
      const rendered = translateText(source);
      if (current !== rendered) element.setAttribute(attr, rendered);
      previous[attr] = { source, rendered };
    }
    originals.set(element, previous);
  };
  if (root.nodeType === 1) translateElement(root);
  for (const element of elements) translateElement(element);
}
